<?php
require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Konten Website';$event=active_event();
if(is_post()){try{verify_csrf();$action=(string)($_POST['action']??'settings');if($action==='settings'){$keys=['site_name','site_description','hero_title','hero_subtitle','footer_description','contact_email','contact_phone','contact_address','instagram_url','youtube_url','tiktok_url'];$stmt=db()->prepare('INSERT INTO settings(setting_key,setting_value,updated_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()');foreach($keys as $key)$stmt->execute([$key,trim((string)($_POST[$key]??''))]);$hero=save_upload('hero_image','content');if($hero)$stmt->execute(['hero_image',$hero]);audit('UPDATE_SITE_CONTENT','settings');flash('success','Konten utama berhasil diperbarui.');}elseif($action==='schedule'&&$event){$sid=(int)($_POST['id']??0);$data=[(int)$event['id'],trim((string)$_POST['title']),$_POST['event_date'],trim((string)$_POST['location']),trim((string)$_POST['description']),(int)$_POST['sort_order'],isset($_POST['is_active'])?1:0];if($sid){$stmt=db()->prepare('UPDATE event_schedules SET event_id=?,title=?,event_date=?,location=?,description=?,sort_order=?,is_active=?,updated_at=NOW() WHERE id=?');$stmt->execute(array_merge($data,[$sid]));}else{$stmt=db()->prepare('INSERT INTO event_schedules(event_id,title,event_date,location,description,sort_order,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,NOW(),NOW())');$stmt->execute($data);}audit('SAVE_SCHEDULE','event_schedules',$sid?:null);flash('success','Jadwal kegiatan disimpan.');}redirect('admin/content.php');}catch(Throwable $e){flash('danger',$e->getMessage());redirect('admin/content.php');}}
$schedules=[];if($event){$s=db()->prepare('SELECT * FROM event_schedules WHERE event_id=? ORDER BY event_date,sort_order');$s->execute([$event['id']]);$schedules=$s->fetchAll();}$editSchedule=null;if(isset($_GET['schedule'])){$s=db()->prepare('SELECT * FROM event_schedules WHERE id=?');$s->execute([(int)$_GET['schedule']]);$editSchedule=$s->fetch();}require __DIR__.'/partials/header.php';
?>
<div class="row g-4"><div class="col-xl-7"><div class="admin-card p-4"><h5 class="mb-4">Identitas dan Konten Utama</h5><form method="post" enctype="multipart/form-data" class="row g-3"><?= csrf_field() ?><input type="hidden" name="action" value="settings"><div class="col-md-6"><label class="form-label">Nama Website</label><input class="form-control" name="site_name" value="<?= e(setting('site_name','Bujang Dayang Bangka Belitung')) ?>"></div><div class="col-md-6"><label class="form-label">Email Kontak</label><input class="form-control" type="email" name="contact_email" value="<?= e(setting('contact_email','')) ?>"></div><div class="col-12"><label class="form-label">Deskripsi Website</label><textarea class="form-control" name="site_description" rows="2"><?= e(setting('site_description','')) ?></textarea></div><div class="col-12"><label class="form-label">Judul Hero</label><input class="form-control" name="hero_title" value="<?= e(setting('hero_title','Pesona Muda, Warisan Budaya Bangka Belitung')) ?>"></div><div class="col-12"><label class="form-label">Subjudul Hero</label><textarea class="form-control" name="hero_subtitle" rows="3"><?= e(setting('hero_subtitle','')) ?></textarea></div><div class="col-12"><label class="form-label">Gambar Hero</label><input class="form-control" type="file" name="hero_image" accept="image/*"></div><div class="col-12"><label class="form-label">Deskripsi Footer</label><textarea class="form-control" name="footer_description" rows="2"><?= e(setting('footer_description','')) ?></textarea></div><div class="col-md-6"><label class="form-label">Nomor WhatsApp</label><input class="form-control" name="contact_phone" value="<?= e(setting('contact_phone','')) ?>"></div><div class="col-md-6"><label class="form-label">Alamat</label><input class="form-control" name="contact_address" value="<?= e(setting('contact_address','')) ?>"></div><div class="col-md-4"><label class="form-label">Instagram</label><input class="form-control" type="url" name="instagram_url" value="<?= e(setting('instagram_url','')) ?>"></div><div class="col-md-4"><label class="form-label">YouTube</label><input class="form-control" type="url" name="youtube_url" value="<?= e(setting('youtube_url','')) ?>"></div><div class="col-md-4"><label class="form-label">TikTok</label><input class="form-control" type="url" name="tiktok_url" value="<?= e(setting('tiktok_url','')) ?>"></div><div class="col-12"><button class="btn btn-admin">Simpan Konten</button></div></form></div></div>
<div class="col-xl-5"><div class="admin-card p-4"><h5 class="mb-4"><?= $editSchedule?'Edit':'Tambah' ?> Jadwal Kegiatan</h5><?php if(!$event):?><div class="alert alert-warning">Aktifkan event terlebih dahulu.</div><?php else:?><form method="post" class="row g-3"><?= csrf_field() ?><input type="hidden" name="action" value="schedule"><input type="hidden" name="id" value="<?= (int)($editSchedule['id']??0) ?>"><div class="col-12"><label class="form-label">Nama Kegiatan</label><input class="form-control" name="title" required value="<?= e($editSchedule['title']??'') ?>"></div><div class="col-12"><label class="form-label">Tanggal dan Waktu</label><input class="form-control" type="datetime-local" name="event_date" required value="<?= $editSchedule&&$editSchedule['event_date']?date('Y-m-d\TH:i',strtotime($editSchedule['event_date'])):'' ?>"></div><div class="col-8"><label class="form-label">Lokasi</label><input class="form-control" name="location" value="<?= e($editSchedule['location']??'') ?>"></div><div class="col-4"><label class="form-label">Urutan</label><input class="form-control" type="number" name="sort_order" value="<?= e($editSchedule['sort_order']??0) ?>"></div><div class="col-12"><label class="form-label">Deskripsi</label><textarea class="form-control" rows="3" name="description"><?= e($editSchedule['description']??'') ?></textarea></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" <?= !isset($editSchedule['is_active'])||$editSchedule['is_active']?'checked':'' ?>><label class="form-check-label">Tampilkan di beranda</label></div></div><div class="col-12 d-grid"><button class="btn btn-admin">Simpan Jadwal</button></div></form><?php endif;?></div><div class="admin-card overflow-hidden mt-4"><div class="p-3"><h6 class="mb-0">Daftar Jadwal</h6></div><div class="list-group list-group-flush"><?php foreach($schedules as $s):?><a href="?schedule=<?= (int)$s['id'] ?>" class="list-group-item list-group-item-action"><strong><?= e($s['title']) ?></strong><small class="d-block text-secondary"><?= indonesia_date($s['event_date'],true) ?> • <?= e($s['location']) ?></small></a><?php endforeach;?><?php if(!$schedules):?><div class="p-4 text-secondary">Belum ada jadwal.</div><?php endif;?></div></div></div></div>
